const express = require('express');
const OpenApiValidator = require('express-openapi-validator');
const path = require('path');
const { VpcPeeringClient, VpcRegistry } = require('../services/cloudNetworking');

const app = express();
app.use(express.json());

app.use(
  OpenApiValidator.middleware({
    apiSpec: path.join(__dirname, 'specs', 'cloud-vpc-openapi.yaml'),
    validateRequests: true
  })
);

app.delete('/api/v1/cloud/vpcs/:vpcId/peerings/:peeringId', async (req, res) => {
  if (!req.user || !req.user.accountId) {
    return res.status(401).json({ error: 'Cloud account authentication required' });
  }

  const { vpcId, peeringId } = req.params;

  // Verify that the VPC belongs to the authenticated cloud account
  const vpcRecord = await VpcRegistry.findOne({
    where: {
      vpcId: vpcId,
      ownerAccountId: req.user.accountId
    }
  });

  if (!vpcRecord) {
    return res.status(403).json({ error: 'Access denied: VPC does not belong to authorized account' });
  }

  try {
    await VpcPeeringClient.terminatePeering(vpcId, peeringId);
    res.status(204).send();
  } catch (err) {
    res.status(500).json({ error: 'Failed to terminate VPC peering connection' });
  }
});

app.listen(5005);
